def import_attributes_from_project(conn_header: ConnHeader, params: ImportAttributesFromProjectParameters) -> dict:
    """
    Imports Line, Fill, ZoneCategory, PenTable, OperationProfile, Composite, Profile and LayerCombination attributes
    from another project or template file into the open project, with their complete definition (symbol and percent
    fills included), like Append or Overwrite by name in Archicad's Attribute Manager. The lines and fills a composite
    or profile uses are matched by name; its building materials and surfaces, and the layers of a layer combination,
    keep their index only with referencesByIndex, since Archicad does not read these types from a closed file. An
    attribute with a reference that cannot be mapped is not imported. A new attribute gets a new guid: Archicad does not
    hand out the guids stored in the source file. An attribute whose name already exists is skipped, or overwritten in
    place with overwriteExisting. dryRun reports what would happen without changing anything. The names are the legacy
    8-bit names of the source file. Available from Archicad 27.
    """
    return conn_header.core.post_tapir_command(
        command="ImportAttributesFromProject",
        parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True),
    )


